package org.apache.commons.lang3;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_29_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Example Java version string
        String version = "1.3.1";

        // Expected integer representation of the version
        int expectedVersionInt = 131;

        // Call the method under test
        float result = SystemUtils.toJavaVersionInt(version);

        // Assert that the result is of type int (this will fail on pre-fix)
        assertTrue("The method should return an integer type", ((Object)result) instanceof Integer);

        // Assert that the result is equal to the expected integer representation
        assertEquals("The method should return an integer representation of the version", expectedVersionInt, (int)result);
    }
}

